data: {"index":1,"delta":{"text":" Kyoto: A Journey Through the Heart of Old Japan\n\nKyoto serves as the cultural and spiritual soul of Japan. While","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" Tokyo represents the country's futuristic ambition, Kyoto is a living museum, preserving the elegance of the Heian period and","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" the austerity of Zen Buddhism. With over 1,600 Buddhist temples and 400 Shinto shrines","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":", the city offers a serene escape into a world of wooden machiya houses, manicured rock gardens, and vermilion","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" gates.\n\n## When to Visit\nKyoto is a city of seasons, and timing your visit can drastically change your","type":"text"},"event_type":"step.delta"}

