event: step.delta
data: {"index":1,"delta":{"text":" breathtaking during this window.\n*   **Autumn (October to November):** Many argue that autumn is superior to spring","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":". The maple trees turn brilliant shades of crimson and gold, framing the city's temples in vivid colors.\n*","type":"text"},"event_type":"step.delta"}

event: step.delta
